1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
client: fix gles3 name

Fix regression introduced in e61d9444c

https://github.com/yquake2/yquake2/issues/1097

Here is the root cause:
The bug was caused by a regression where the renderer was incorrectly set to "gles" instead of the intended "gles3" when the current renderer was "gl3". This misconfiguration could lead to improper rendering behavior in the application.

Here is the patch:
  */
 void
 VID_CheckChanges(void)
 {
 	// Hack around renderers that still abuse vid_fullscreen
 	// to communicate restart requests to the client.
 	ref_restart_t rs;

 	if (restart_state == RESTART_UNDEF)
 	{
 		if (vid_fullscreen->modified)
 		{
 			rs = RESTART_FULL;
 			vid_fullscreen->modified = false;
 		} else {
 			rs = RESTART_NO;
 		}
 	} else {
 		rs = restart_state;
 		restart_state = RESTART_NO;
 	}

 	if (rs == RESTART_FULL)
 	{
 		// Stop sound, because the clients blocks while
 		// we're reloading the renderer. The sound system
 		// would screw up it's internal timings.
 		S_StopAllSounds();

 		// Reset the client side of the renderer state.
 		cl.refresh_prepped = false;
 		cl.cinematicpalette_active = false;

 		// More or less blocks the client.
 		cls.disable_screen = true;

 		// Mkay, let's try our luck.
 		while (!VID_LoadRenderer())
 		{
 			// We try: custom -> gl3 -> gles3 -> gl1 -> soft.
 			if ((strcmp(vid_renderer->string, "gl3") != 0) &&
 				(strcmp(vid_renderer->string, "gles3") != 0) &&
 				(strcmp(vid_renderer->string, "gl1") != 0) &&
 				(strcmp(vid_renderer->string, "soft") != 0))
 			{
 				Com_Printf("Retrying with gl3...\n");
 				Cvar_Set("vid_renderer", "gl3");
 			}
 			else if (strcmp(vid_renderer->string, "gl3") == 0)
 			{
 				Com_Printf("Retrying with gles3...\n");
-				Cvar_Set("vid_renderer", "gles");
+				Cvar_Set("vid_renderer", "gles3");
 			}
 			else if (strcmp(vid_renderer->string, "gles3") == 0)
 			{
 				Com_Printf("Retrying with gl1...\n");
 				Cvar_Set("vid_renderer", "gl1");
 			}
 			else if (strcmp(vid_renderer->string, "gl1") == 0)
 			{
 				Com_Printf("Retrying with soft...\n");
 				Cvar_Set("vid_renderer", "soft");
 			}
 			else if (strcmp(vid_renderer->string, "soft") == 0)
 			{
 				// Sorry, no usable renderer found.
 				Com_Error(ERR_FATAL, "No usable renderer found!\n");
 			}
 		}

 		// Unblock the client.
 		cls.disable_screen = false;
 	}

 	if (rs == RESTART_PARTIAL)
 	{
 		cl.refresh_prepped = false;
 	}
 }



